        shayariItem(666, "फूलों की खुशबू तो कुछ घंटों की मेहमान होती है,\nपर तेरे बदन की खुशबू तो साँसों में बस जाती है।", "_ शायरी", cat, "ख़ुशबू"),
        shayariItem(667, "तुम हँसती हो तो गालों में गड्ढे पड़ते हैं,\nऔर उन्हीं गड्ढों में हम जैसे आशिक़ फिसल पड़ते हैं।", "दिल की बात", cat, "डिंपल"),
        shayariItem(668, "सारी शरीफ़ बातें दिन के उजाले के लिए रखो,\nरात तो बनी ही है थोड़ी बहुत गुस्ताख़ी करने के लिए।", "_ शायरी", cat, "गुस्ताख़ी"),
        shayariItem(669, "तुम्हारी कमर पर बंधा वो काला धागा,\nहर बार मेरे ध्यान को भटकाने की साज़िश करता है।", "दिल की बात", cat, "काला धागा"),
        shayariItem(670, "आओ पास बैठो, आज कोई किस्सा नहीं सुनाना,\nबस तुम्हें जी भर के देखना और महसूस करना है।", "_ शायरी", cat, "महसूस"),
        shayariItem(671, "अगर इश्क़ में थोड़ी शरारत न हो,\nतो मोहब्बत भी किसी उबाऊ किताब जैसी लगती है।", "दिल की बात", cat, "शरारत"),
        shayariItem(672, "तेरे होंठों के पास वाला वो छोटा सा तिल,\nबड़ी बेदर्दी से लूट लेता है हर देखने वाले का दिल।", "_ शायरी", cat, "तिल"),
        shayariItem(673, "दरवाज़े की कुंडी और धीमा संगीत,\nदोनों गवाह बनेंगे आज हमारी इस प्यारी सी जीत के।", "दिल की बात", cat, "संगीत"),
        shayariItem(674, "आज तुम्हारी आँखों में जो चमक है,\nलगता है दिल में कोई मज़ेदार प्लान चल रहा है।", "_ शायरी", cat, "प्लान"),
        shayariItem(675, "कपड़ों से ज़्यादा तुम आत्मविश्वास में जँचती हो,\nजब भी चलती हो तो हर नज़र बस तुम पर टिकती है।", "दिल की बात", cat, "स्टाइल"),
        shayariItem(676, "कभी-कभी चुपचाप हाथ पकड़कर आँखों में देखना,\nहज़ार रोमांटिक बातों से ज़्यादा असर कर जाता है।", "_ शायरी", cat, "असर"),
        shayariItem(677, "तुम कहो तो आज मौसम का पूरा फायदा उठाएँ,\nभीगती शाम में एक कप गरम कॉफ़ी साथ बनाएँ।", "दिल की बात", cat, "शाम"),
        shayariItem(678, "चुपके से गाल चूमकर भाग जाने की आदत,\nतुम्हारे अंदर आज भी बड़ी प्यारी है।", "_ शायरी", cat, "आदत"),
        shayariItem(679, "हर बार मर्यादा की बात करना भी ठीक नहीं,\nकभी-कभी दिल की बेताबी को भी सुन लेना चाहिए।", "दिल की बात", cat, "बेताबी"),
        shayariItem(680, "मेरी शर्ट पहनकर जब तुम घर में घूमती हो,\nउस वक़्त दुनिया की सबसे हसीन तस्वीर लगती हो।", "_ शायरी", cat, "तस्वीर"),
        shayariItem(681, "तेरी बाहों का घेरा ही मेरा सबसे पसंदीदा ठिकाना है,\nयहाँ आने के बाद फिर कहीं जाने का मन नहीं करता।", "दिल की बात", cat, "बाहें"),
        shayariItem(682, "मज़ाक़-मज़ाक़ में आज कुछ ज़्यादा ही क़रीब आ गए,\nअब पीछे हटने का मन भी नहीं और इरादा भी नहीं।", "_ शायरी", cat, "मज़ाक़"),
        shayariItem(683, "रंगों का त्योहार तो साल में एक बार आता है,\nपर तेरी सोहबत में तो हर शाम रंगीन होती है।", "दिल की बात", cat, "रंगीन"),
        shayariItem(684, "बातें कम और इशारे ज़्यादा हो रहे हैं आजकल,\nलगता है दोनों तरफ़ बेसब्री बढ़ती जा रही है।", "_ शायरी", cat, "बेसब्री"),
        shayariItem(685, "काजल थोड़ा फैल भी जाए तो क्या हुआ,\nसजने से ज़्यादा मज़ा तेरी सादगी में आता है।", "दिल की बात", cat, "काजल"),
        shayariItem(686, "तुमने जो आज ये लाल रंग पहना है,\nसच्ची, दिल पर सीधा तीर चला है।", "_ शायरी", cat, "लाल रंग"),
        shayariItem(687, "साँसों का शोर जब बातचीत से ज़्यादा हो जाए,\nसमझ लेना दो दिल एक-दूसरे में पूरी तरह खो गए हैं।", "दिल की बात", cat, "साँसें"),
        shayariItem(688, "नटखट निगाहें और होंठों पर हल्की सी बाइट,\nबस इतना ही काफ़ी है बनाने को ये रात ब्राइट।", "_ शायरी", cat, "हॉट • अंदाज़"),
        shayariItem(689, "थोड़ी सी ज़िद और थोड़ा सा नखरा अच्छा लगता है,\nजब सामने वाला प्यार से मनाने वाला हो।", "दिल की बात", cat, "नखरा"),
        shayariItem(690, "चाँद भी छुप गया बादलों में आज तुम्हें देखकर,\nक्योंकि असली चमक तो इस कमरे के अंदर है।", "_ शायरी", cat, "चमक"),
        shayariItem(691, "सुकून और रोमांच दोनों एक साथ मिलें जहाँ,\nबस वही जगह है तेरे दिल के पास।", "दिल की बात", cat, "रोमांच"),
        shayariItem(692, "मेरी तन्हाई भी तेरे नाम से महकती है,\nजब तू पास हो तो हर धड़कन तेज़ बहकती है।", "_ शायरी", cat, "बहकना"),
        shayariItem(693, "कहने को तो हम बड़े समझदार बनते हैं बाहर,\nपर तेरे सामने आते ही सारी अक़्ल घास चरने चली जाती है।", "दिल की बात", cat, "दीवानगी"),
        shayariItem(694, "तेरे होठों से लगा हुआ पानी भी अमृत जैसा लगता है,\nइश्क़ में आकर इंसान ऐसे ही पागल हो जाता है।", "_ शायरी", cat, "पागलपन"),
        shayariItem(695, "रात की चादर में लिपटकर बस तेरी बातें करनी हैं,\nबाकी सारी शिकायतें कल सुबह के लिए रखनी हैं।", "दिल की बात", cat, "रात"),
        shayariItem(696, "इतनी बेरहमी से दिल न चुराया करो,\nकम से कम पास आने का एक मौका तो दिया करो।", "_ शायरी", cat, "मौका"),
        shayariItem(697, "तुम मेरी चाय की पत्ती और मैं तुम्हारी शक्कर,\nदोनों मिल जाएं तो बन जाए ज़िंदगी का सबसे कड़क स्वाद।", "दिल की बात", cat, "डबल मीनिंग"),
        shayariItem(698, "आँख मारकर मुस्कुरा देना तेरा वो पुराना स्टाइल,\nआज भी मेरे चेहरे पर तुरंत हँसी ले आता है।", "_ शायरी", cat, "स्टाइल"),
        shayariItem(699, "जब तुम बाल पकड़कर एक तरफ़ करती हो,\nतो सच में कयामत ढाने का पूरा इंतज़ाम करती हो।", "दिल की बात", cat, "कयामत"),
        shayariItem(700, "जवानी की इस दहलीज़ पर बस इतना ही कहना है,\nखुलकर जियो, खुलकर चाहो, क्योंकि ये वक़्त फिर नहीं आना है।", "_ शायरी", cat, "जवानी • मस्ती")
    )
}
